package main

import (
	"encoding/json"
	"fmt"
	"html/template"
	"io/fs"
	"os"
	"path"
)

// Entry 是导出的结构体，字段上的 json tag 决定 JSON 怎么对上它
type Entry struct {
	Title string `json:"title"`
	Notes string `json:"notes"`
}

// Load 解析一段 JSON，缺字段就返回 error
func Load(raw []byte) (Entry, error) {
	var e Entry
	if err := json.Unmarshal(raw, &e); err != nil {
		return Entry{}, err
	}
	if e.Title == "" {
		// tag 拼错不会报错，只能自己查
		return Entry{}, fmt.Errorf("没有 title 字段，检查 json tag 拼写")
	}
	return e, nil
}

// pageView 是模板要的数据，Body 是 template.HTML 所以不会被转义
type pageView struct {
	Title string
	Body  template.HTML
}

func main() {
	// 先落一个配置文件
	if err := os.MkdirAll("data", 0o755); err != nil {
		panic(err)
	}
	raw := []byte(`{"title":"整型","notes":"溢出会绕回成负数"}`)
	if err := os.WriteFile("data/entry.json", raw, 0o644); err != nil {
		panic(err)
	}

	// 再用 io/fs 按斜杠路径读回来（别用 filepath.Join）
	data, err := fs.ReadFile(os.DirFS("."), path.Join("data", "entry.json"))
	if err != nil {
		panic(err)
	}

	e, err := Load(data)
	if err != nil {
		fmt.Fprintln(os.Stderr, "加载失败:", err)
		os.Exit(1)
	}

	tmpl := template.Must(template.New("entry").Parse(`<h2>{{.Title}}</h2><p>{{.Body}}</p>`))
	_ = tmpl.Execute(os.Stdout, pageView{
		Title: e.Title,
		Body:  template.HTML("<em>" + e.Notes + "</em>"),
	})
}
